    \filldraw [black] (B) circle (1.5pt);
    \filldraw [black] (C) circle (1.5pt);
    \filldraw [black] (M) circle (1.5pt);
    \draw
    ($(A)!0.5!(C)$)node[rotate=20]{$/$} ($(A)!0.5!(B)$)node[rotate=20]{$/$};
